int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *orphan, *next;
    int ret = 0;

    if (!EXT4_HAS_JOURNAL(inode->i_sb) || !sbi->s_orphan)
        return 0;

    mutex_lock(&sbi->s_orphan_lock);
    list_for_each_entry_safe(orphan, next, &sbi->s_orphan_list, list) {
        if (orphan->ino == inode->i_ino) {
            list_del(&orphan->list);
            kfree(orphan);
            break;
        }
    }
    mutex_unlock(&sbi->s_orphan_lock);

    if (handle && !ret) {
        if (ext4_journal_get_write_access(handle, ei->i_bh) < 0)
            ret = -EINVAL;
        if (!ret) {
            ei->i_flags &= ~EXT4_ORPHAN_FLAG;
            if (ext4_journal_dirty_metadata(handle, ei->i_bh) < 0)
                ret = -EINVAL;
        }
    }

    if (ret < 0)
        ext4_orphan_unlock(inode);

    return ret;
}

int ext4_orphan_del(handle_t *handle, struct inode *inode)
{
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *orphan, *next;
    int ret = 0;

    if (!sbi->s_journal)
        return 0;

    if (!ei->i_dtime && !atomic_read(&ei->i_count)) {
        return -EINVAL;
    }

    mutex_lock(&sbi->s_orphan_lock);

    list_for_each_entry_safe(orphan, next, &sbi->s_orphan, list) {
        if (orphan->ino == inode->i_ino) {
            list_del_init(&orphan->list);
            kfree(orphan);
            break;
        }
    }

    if (handle) {
        ret = ext4_mark_inode_dirty(handle, inode);
        if (ret < 0) {
            mutex_unlock(&sbi->s_orphan_lock);
            return ret;
        }
    }

    mutex_unlock(&sbi->s_orphan_lock);
    return ret;
}

